//autogenerated routine code, DO NOT TOUCH!
use crate::chassis::Chassis;
use crate::robot::Robot;
use crate::subsystems::*;
use vexide::math::*;
use vexide::prelude::*;
use alloc::rc::Rc;
use core::time::Duration;
use crate::helpers::*;
use crate::motion_control::ramsete::*;
use crate::localization::dsr::Wall;
use futures_util::future::join;
use vexide::smart::motor::BrakeMode;

pub async fn run(robot: &mut Robot) {
	let _log_task = spawn(Chassis::log_pose(Rc::clone(&robot.chassis.pose)));
	// Start
	robot.chassis.set_pose(Pose::new(68.8987, 8.98857, Angle::from_degrees(270.0)));

	// Action 1
	robot.lift.score_height(0, "alliance");
	robot.toggle.auto_toggle_loop(Duration::from_millis(700)).await;
	robot.chassis.distance_reset(&robot.dsrs.front, Wall::Bottom).await;

	// Motion 1
	let mut motion1 = MotionProfile::new("far_4/motion1.json");
	join(robot.chassis.drive_along(&mut motion1), async {
		//robot.chassis.end_motion_when(|| robot.lift.at_alliance_goal(), true).await;
	}).await;

	// Action 2
	robot.lift.cascade_to_height(10.0);
	robot.chassis.drive_raw_v(-10.0, -10.0, Duration::from_millis(200)).await;
	robot.lift.claw_open();
	robot.chassis.drive_raw_v(-5.0, -5.0, Duration::from_millis(100)).await;
	robot.chassis.goal_reset((48.3, 25.1));

	// Action 3
	robot.lift.matchload();

	// Motion 2
	let mut motion2 = MotionProfile::new("far_4/motion2.json");
	robot.chassis.drive_along(&mut motion2).await;

	// Action 4
	robot.chassis.distance_reset(&robot.dsrs.right, Wall::Bottom).await;

	// Motion 3
	let mut motion3 = MotionProfile::new("far_4/motion3.json");
	robot.chassis.drive_along(&mut motion3).await;

	// Action 5
	//robot.chassis.swing_turn(100.0, 60, 1000.0, "right").await;
	robot.chassis.drive_raw_v(-12.0, -10.0, Duration::from_millis(400)).await;
	robot.lift.claw_close();
	robot.chassis.drive_raw_v(-12.0, -10.0, Duration::from_millis(150)).await;
	robot.chassis.distance_reset(&robot.dsrs.back, Wall::Bottom).await;
	robot.chassis.turn_with_conditions(60.0, 30.0, 50.0, false, 1000.0, "none").await;
	robot.chassis.turn_with_conditions(100.0, 10.0, 35.0, false, 1000.0, "right").await;

	// Action 6
	robot.lift.score_height(1, "alliance");

	// Motion 4
	let mut motion4 = MotionProfile::new("far_4/motion4.json");
	robot.chassis.drive_along(&mut motion4).await;

	// Motion 5
	let mut motion5 = MotionProfile::new("far_4/motion5.json");
	join(robot.chassis.drive_along(&mut motion5), async {
		robot.chassis.end_motion_when(|| robot.lift.at_alliance_goal(), true).await;
	}).await;

	// Action 7
	robot.lift.drop();
	robot.chassis.drive_raw_v(-5.0, -5.0, Duration::from_millis(450)).await;
	robot.chassis.goal_reset((48.3, 25.1));
	robot.lift.matchload();

	// Motion 6
	let mut motion6 = MotionProfile::new("far_4/motion6.json");
	robot.chassis.drive_along(&mut motion6).await;

	// Action 8
	robot.chassis.turn(100.0, 315.0, 1000.0).await;
	sleep(Duration::from_millis(350)).await;

	// Action 9
	//robot.chassis.distance_reset(&robot.dsrs.front, Wall::Bottom).await;

	// Motion 7
	let mut motion7 = MotionProfile::new("far_4/motion7.json");
	join(robot.chassis.drive_along(&mut motion7), async {
		robot.lift.auto_clamp_task(2500).await;
	}).await;

	// Action 10
	robot.lift.score_height(2, "alliance");

	// Motion 8
	let mut motion8 = MotionProfile::new("far_4/motion8.json");
	join(robot.chassis.drive_along(&mut motion8), async {
		//robot.chassis.end_motion_when(|| robot.lift.at_alliance_goal(), true).await;
	}).await;

	// Action 11
	robot.lift.drop();
	robot.chassis.drive_raw_v(-4.0, -4.0, Duration::from_millis(450)).await;
	robot.lift.matchload();
	robot.chassis.goal_reset((48.3, 25.1));

	// Motion 9
	let mut motion9 = MotionProfile::new("far_4/motion9.json");
	robot.chassis.drive_along(&mut motion9).await;

	// Motion 10
	let mut motion10 = MotionProfile::new("far_4/motion10.json");
	join(robot.chassis.drive_along(&mut motion10), async {
		robot.lift.auto_clamp_task(3000).await;
		sleep(Duration::from_millis(200)).await;
		robot.chassis.end_motion();
	}).await;

	// Action 12
	robot.lift.score_height(3, "alliance");

	// Motion 11
	let mut motion11 = MotionProfile::new("far_4/motion11.json");
	join(robot.chassis.drive_along(&mut motion11), async {
		//robot.chassis.end_motion_when(|| robot.lift.at_alliance_goal(), true).await;
	}).await;

	// Action 13
	robot.lift.drop();
	robot.chassis.drive_raw_v(-5.0, -5.0, Duration::from_millis(300)).await;
	robot.lift.matchload();
	robot.chassis.goal_reset((48.3, 25.1));

}
